package org.agentfrc.lesson;
import java.nio.file.*;import java.security.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
public class MovingNoteTest {
 static Path out;static Properties input=new Properties(),results=new Properties();static byte[] raw;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}static double d(String k){return Double.parseDouble(input.getProperty(k));}
 @BeforeAll static void hal()throws Exception{out=Path.of(Objects.requireNonNull(System.getenv("FRC_MOVING_NOTE_OUTPUT"),"Fresh nested native runner required"));raw=Files.readAllBytes(out.resolve("input.properties"));input.load(new java.io.ByteArrayInputStream(raw));assertEquals("frc-moving-note-input/v1",input.getProperty("schema"));assertEquals(input.getProperty("experimentSha256"),sha(Files.readAllBytes(out.resolve("experiment.json"))));for(String v:new String[]{"compressed","nominal"})assertEquals(input.getProperty(v+"PropertiesSha256"),sha(Files.readAllBytes(out.resolve("baseline/"+v+"/properties.json"))));assertEquals(-.220,d("initialXM"),1e-12);assertEquals(.0254,d("initialZM"),1e-12);assertEquals(-.7,d("floorMinXM"),1e-12);assertEquals(.7,d("floorMaxXM"),1e-12);edu.wpi.first.hal.HAL.initialize(500,0);}
 static NoteContactPlant.Config note(double floor,boolean nominal){return new NoteContactPlant.Config(d("massKg"),d("majorRadiusM"),d("minorRadiusM"),d("rollerSpanM"),d("rollerRadiusM"),d(nominal?"nominalRollerInertiaKgM2":"rollerInertiaKgM2"),d(nominal?"nominalRollerZM":"rollerZM"),d("gear"),floor);}
 static MovingNotePlant.Config config(double ground,double floor,boolean nominal){return new MovingNotePlant.Config(note(floor,nominal),ground);}
 @AfterAll static void write()throws Exception{results.setProperty("inputSha256",sha(raw));for(Class<?> c:new Class<?>[]{MovingNotePlant.class,MovingNoteController.class,MovingNoteRig.class,MovingNotePassageAssessor.class})results.setProperty(c.getSimpleName()+"ClassSha256",sha(c.getResourceAsStream(c.getSimpleName()+".class").readAllBytes()));results.setProperty("capture","unestablished");results.setProperty("engineeringAcceptance","blocked");try(var w=Files.newBufferedWriter(out.resolve("result.properties"))){results.store(w,"Moving development evidence only");}}
 static double[] values(MovingNotePlant.Sample a){return new double[]{a.bodyX(),a.bodyV(),a.noteX(),a.noteZ(),a.noteVx(),a.noteVz(),a.leftAngle(),a.leftOmega(),a.rightAngle(),a.rightOmega(),a.sleeveAngle(),a.sleeveOmega(),a.bus(),a.batteryAmps(),a.mechanicalResidual(),a.normalLoss(),a.pieceFrictionLoss(),a.groundSlipLoss(),a.maxEvaluatedRollerNormal()};}
 record Run(List<double[]> rows,String category){}
 static Run run(double ground,double floor,boolean nominal,int steps)throws Exception{String id=(nominal?"nominal":"compressed")+"-ground"+ground+"-floor"+floor+"-steps"+steps;var rows=new ArrayList<double[]>();StringBuilder csv=new StringBuilder("t,bodyX,bodyV,noteX,noteZ,noteVx,noteVz,leftAngle,leftOmega,rightAngle,rightOmega,sleeveAngle,sleeveOmega,bus,current,residual,normalLoss,pieceFrictionLoss,groundSlipLoss,maxRollerNormal,normalTotal,relativeX,controller,mechanism,pulses,passage\n");String outcome="unobserved",phase="not-run",mechanism="not-run",tick="none";boolean passage=false,contact=false;double maximum=0;int pulses=0;try(var rig=new MovingNoteRig(config(ground,floor,nominal))){for(int i=0;i<220;i++){try{var a=rig.step(true,steps);rows.add(values(a));maximum=Math.max(maximum,a.maxEvaluatedRollerNormal());phase=rig.controller.phase().toString();mechanism=rig.controller.mechanism.phase().toString();pulses=rig.controller.mechanism.pulses();passage=rig.assessor.verified();contact=rig.assessor.contacted();csv.append((i+1)*.02);for(double v:values(a))csv.append(',').append(v);csv.append(',').append(a.normalTotal()).append(',').append(a.relativeX()).append(',').append(phase).append(',').append(mechanism).append(',').append(pulses).append(',').append(passage).append('\n');assertTrue(Math.abs(a.mechanicalResidual())<.001,"Mechanical residual");assertTrue(a.normalLoss()>=0&&a.pieceFrictionLoss()>=0&&a.groundSlipLoss()>=0);outcome=phase.equals("FAULT")?"controller-fault":phase.equals("STOP")?"sensor-stop-not-capture":"approach-without-stop";}catch(IllegalArgumentException e){maximum=Math.max(maximum,rig.maxEvaluatedRollerNormal());boolean electrical=e.getMessage().contains("Unsupported regeneration");boolean model=e.getMessage().contains("Finite world floor or moving state domain")||e.getMessage().contains("Contact state domain")||e.getMessage().contains("Excessive assumed compression")||e.getMessage().contains("Unsupported nonpositive drive normal support");assertTrue(electrical||model,e.getMessage());outcome=(electrical?"unsupported-electrical: ":"unsupported-model: ")+e.getMessage();tick="["+(i*.02)+","+((i+1)*.02)+"]";phase=rig.controller.phase().toString();mechanism=rig.controller.mechanism.phase().toString();pulses=rig.controller.mechanism.pulses();passage=rig.assessor.verified();contact=rig.assessor.contacted();break;}}}Files.writeString(out.resolve(id+".csv"),csv,StandardOpenOption.CREATE_NEW);results.setProperty(id+".outcome",outcome);results.setProperty(id+".controller",phase);results.setProperty(id+".mechanism",mechanism);results.setProperty(id+".pulses",Integer.toString(pulses));results.setProperty(id+".contactObserved",Boolean.toString(contact));results.setProperty(id+".orderedPassage",Boolean.toString(passage));results.setProperty(id+".maxEvaluatedRollerNormal",Double.toString(maximum));results.setProperty(id+".unsupportedTick",tick);assertFalse(rows.isEmpty(),"Must execute a supported prefix");return new Run(rows,outcome.split(":")[0]);}
 @Test void nativePairedMovingProfilesAndRefinement()throws Exception{double[] max=new double[19];for(boolean nominal:new boolean[]{false,true})for(double ground:new double[]{0,.8})for(double floor:new double[]{0,.2}){var a=run(ground,floor,nominal,200);var b=run(ground,floor,nominal,400);assertEquals(a.category,b.category);assertTrue(Math.abs(a.rows.size()-b.rows.size())<=1,"Failure tick convergence");for(int i=0;i<Math.min(a.rows.size(),b.rows.size());i++)for(int j=0;j<19;j++)max[j]=Math.max(max[j],Math.abs(a.rows.get(i)[j]-b.rows.get(i)[j]));}double[] tol={1e-4,.001,1e-4,1e-5,.001,.001,.002,.01,.002,.01,.002,.01,.01,.5,.001,.001,.001,.001,.02};for(int j=0;j<19;j++){results.setProperty("refinementMax."+j,Double.toString(max[j]));assertTrue(max[j]<tol[j],"Refinement component "+j+" delta="+max[j]);}}
 @Test void stationaryPieceAndNoCommandHaveNoHorizontalMotion(){var p=new MovingNotePlant(config(.8,.2,false));for(int i=0;i<100;i++){var a=p.step(0,0,0,.0001);assertEquals(0,a.bodyX(),1e-14);assertEquals(-.220,a.noteX(),1e-14);assertEquals(0,a.bodyV(),1e-14);assertEquals(0,a.noteVx(),1e-14);assertEquals(0,a.rollerNormal());}}
 @Test void zeroTractionSpinsWheelsWithoutApproach(){var p=new MovingNotePlant(config(0,.2,false));MovingNotePlant.Sample a=null;for(int i=0;i<1000;i++)a=p.step(-.05,-.05,-.12,.0001);assertEquals(0,a.bodyX(),1e-14);assertEquals(-.220,a.noteX(),1e-14);assertTrue(a.leftOmega()<0);assertNotEquals(a.bodyX(),a.leftAngle()*.0762);assertEquals(0,a.maxEvaluatedRollerNormal());}
 @Test void contactMomentumAndFrameTranslation(){var c=config(0,0,false);var init=new MovingNotePlant.Initial(0,-.15,0,0,-.168,.0254,0,0,-10);var shifted=new MovingNotePlant.Initial(.1,-.15,0,0,-.068,.0254,0,0,-10);var a=new MovingNotePlant(c,init);var b=new MovingNotePlant(c,shifted);for(int i=0;i<100;i++){var x=a.step(0,0,0,.0001);var y=b.step(0,0,0,.0001);assertEquals(-6.75,45*x.bodyV()+c.note().mass()*x.noteVx(),1e-10);assertEquals(x.relativeX(),y.relativeX(),1e-12);assertEquals(x.bodyV(),y.bodyV(),1e-12);assertEquals(x.noteVx(),y.noteVx(),1e-12);assertTrue(Math.abs(x.mechanicalResidual())<.001);}}
 @Test void verticalReactionChangesTractionNormal(){var c=config(.8,0,false);var down=new MovingNotePlant(c,new MovingNotePlant.Initial(0,0,0,0,-.168,.0254,0,0,-10)).sample(0,0,0);assertTrue(down.normalTotal()<45*9.80665);var up=new MovingNotePlant(c,new MovingNotePlant.Initial(0,0,0,0,-.210,.06,0,0,10)).sample(0,0,0);assertTrue(up.normalTotal()>45*9.80665);assertThrows(IllegalArgumentException.class,()->new MovingNotePlant(c,new MovingNotePlant.Initial(0,0,0,0,0,.03,0,5,0)).sample(0,0,0));}
 @Test void wheelReactionAndSharedBusAreCoupled(){assertThrows(IllegalArgumentException.class,()->new MovingNotePlant(null));assertThrows(IllegalArgumentException.class,()->new MovingNotePlant(config(.8,.2,false)).sample(-.05,0,0));assertThrows(IllegalArgumentException.class,()->new MovingNotePlant(config(.8,.2,false),new MovingNotePlant.Initial(0,0,-1,0,-.220,.0254,0,0,0)));var both=new MovingNotePlant(config(.8,.2,false));var combined=both.sample(-.05,-.05,-.12);var only=both.sample(-.05,-.05,0);assertTrue(combined.bus()<only.bus());double conductance=2*.05*.05/(12.0/210)+.12*.12/(12.0/105);assertEquals(12/(1+.02*conductance),combined.bus(),1e-10);assertEquals((12-combined.bus())/.02,combined.batteryAmps(),1e-10);var init=new MovingNotePlant.Initial(0,0,-1,-1,-.220,.0254,0,0,0);var free=new MovingNotePlant(config(0,.2,false),init).step(-.05,-.05,0,.0001);var loaded=new MovingNotePlant(config(.8,.2,false),init).step(-.05,-.05,0,.0001);assertTrue(Math.abs(loaded.leftOmega())<Math.abs(free.leftOmega()));assertTrue(loaded.batteryAmps()>free.batteryAmps());}
 @Test void actualSignedControllerAndEncoderFault(){try(var c=new MovingNoteController()){var beam=new edu.wpi.first.wpilibj.simulation.DIOSim(2);beam.setValue(true);edu.wpi.first.wpilibj.simulation.RoboRioSim.setVInVoltage(12);c.periodic(true);assertTrue(new edu.wpi.first.wpilibj.simulation.PWMSim(1).getSpeed()<0);assertTrue(new edu.wpi.first.wpilibj.simulation.PWMSim(2).getSpeed()<0);}try(var rig=new MovingNoteRig(config(.8,.2,false),-1,0)){try{for(int i=0;i<10;i++)rig.step(true,200);}catch(IllegalArgumentException e){assertTrue(e.getMessage().contains("Unsupported regeneration"));}assertEquals(MovingNoteController.Phase.FAULT,rig.controller.phase());}}
 @Test void actualEncoderTravelIsNotBodyTruth(){try(var rig=new MovingNoteRig(config(0,.2,false))){var failure=assertThrows(IllegalArgumentException.class,()->{for(int i=0;i<5;i++)rig.step(true,200);});assertTrue(failure.getMessage().startsWith("Unsupported regeneration"));var a=rig.lastSample();assertEquals(0,a.bodyX(),1e-14);assertTrue(a.leftAngle()<0);assertTrue(rig.controller.leftRate()<0);assertEquals(-.220,a.noteX(),1e-14);}}
 static void segment(MovingNotePassageAssessor a,double t0,double t1,double x0,double x1,double normal){int n=(int)Math.ceil((t1-t0)/.0001);for(int i=1;i<=n;i++)a.observe(t0+(t1-t0)*i/n,x0+(x1-x0)*i/n,.0254,.1,normal);}
 @Test void orderedAssessorRejectsNoContactAndRebound(){var c=note(.2,false);var a=new MovingNotePassageAssessor(c);a.observe(0,-.22,.0254,.1,0);segment(a,0,.3,-.22,.23,0);assertFalse(a.verified());var b=new MovingNotePassageAssessor(c);b.observe(0,-.168,.0254,.1,1);segment(b,0,.1,-.168,0,1);segment(b,.1,.2,0,.20,0);segment(b,.2,.41,.20,.23,0);assertTrue(b.verified());segment(b,.41,.42,.23,0,1);assertFalse(b.verified());assertTrue(b.recontact());var r=new MovingNotePassageAssessor(c);r.observe(0,-.168,.0254,.1,1);segment(r,0,.1,-.168,0,1);segment(r,.1,.2,0,-.01,1);segment(r,.2,.6,-.01,.25,0);assertFalse(r.verified());assertTrue(r.reversed());assertThrows(IllegalArgumentException.class,()->r.observe(.6,.25,.0254,.1,0));assertThrows(IllegalArgumentException.class,()->r.observe(.61,.25,.0254,.1,0));}
 @Test void timeoutDisableAndBeamFaultRemainLatched(){try(var c=new MovingNoteController()){var beam=new edu.wpi.first.wpilibj.simulation.DIOSim(2);beam.setValue(true);var l=edu.wpi.first.wpilibj.simulation.EncoderSim.createForChannel(4);var r=edu.wpi.first.wpilibj.simulation.EncoderSim.createForChannel(6);edu.wpi.first.wpilibj.simulation.RoboRioSim.setVInVoltage(12);for(int i=0;i<211;i++){l.setCount(-i);r.setCount(-i);c.periodic(true);}assertEquals(MovingNoteController.Phase.FAULT,c.phase());assertEquals(0,new edu.wpi.first.wpilibj.simulation.PWMSim(1).getSpeed());assertEquals(0,new edu.wpi.first.wpilibj.simulation.PWMSim(0).getSpeed());c.periodic(true);assertEquals(MovingNoteController.Phase.FAULT,c.phase());}try(var rig=new MovingNoteRig(config(.8,.2,false),1,1)){rig.step(true,200);assertEquals(MovingNoteController.Phase.FAULT,rig.controller.phase());}try(var rig=new MovingNoteRig(config(.8,.2,false))){rig.step(false,200);rig.step(true,200);assertEquals(MovingNoteController.Phase.FAULT,rig.controller.phase());}}
}


